package com.shipflow.order;
import org.junit.jupiter.api.Test; import java.nio.file.*; import static org.assertj.core.api.Assertions.assertThat;
class ShipmentOrderMapperXmlTest { @Test void writesAllOrderAggregateRowsAndKeepsTenantPredicates(){try{String xml=Files.readString(Path.of("src/main/resources/mapper/order/ShipmentOrderMapper.xml")); assertThat(xml).contains("shipment_order","shipment_quote_snapshot","shipment_address","shipment_package","package_status","shipment_item","product_name_en","declared_value","origin_country","audit_log","tenant_id=#{tenantId}","transitionStatus","advanceDraftVersion","current_status='DRAFT' AND version=#{version}","version,created_at","DELETE si","chargeable_weight").doesNotContain("SELECT *","country_of_origin","declared_chargeable_weight,status","hs_code","item.hsCode","shipment_order (tenant_id,order_no,idempotency_key,store_id,quote_id,channel_id,current_status,origin_country,destination_country,declared_weight,declared_length,declared_width,declared_height,declared_volume_weight,declared_chargeable_weight");}catch(Exception e){throw new AssertionError(e);}} @Test void callerWorkbenchFilterKeepsTenantAndActiveStoreScope(){try{String xml=Files.readString(Path.of("src/main/resources/mapper/order/ShipmentOrderMapper.xml"));assertThat(xml).contains("callerScope","sys_user_store_scope","uss.status='ACTIVE'","callerWorkbenchFilter","fee_adjustment fa","PENDING_CONFIRMATION","shipment_address a","address_type='RECEIVER'","address_type='SENDER'","findPageForCaller","countForCaller");}catch(Exception e){throw new AssertionError(e);}} @Test void idempotencyXmlHasTenantScope(){try{String xml=Files.readString(Path.of("src/main/resources/mapper/order/ShipmentOrderIdempotencyMapper.xml"));assertThat(xml).contains("scope_tenant_id=#{tenantId}","resource_type='SHIPMENT_ORDER'");}catch(Exception e){throw new AssertionError(e);}} }
